// 🧹 CLEAN CALENDAR IDS
// =========================
workshopItems.forEach(w => {
  w.calendar_id = (w.calendar_id || '').trim();
});

// =========================
// BUILD BUSY MAP (Google)
// =========================
const busyByCalendar = {};

allResults.forEach((result) => {
  let slots = [];
  if (result.busy && Array.isArray(result.busy)) {
    slots = result.busy;
  } else if (Array.isArray(result)) {
    slots = result;
  } else if (result.start || result.end) {
    slots = [result];
  }

  const calId = (result.calendar_id || '').trim();
  if (!calId) return;

  if (!busyByCalendar[calId]) busyByCalendar[calId] = [];

  slots.forEach(b => {
    const start = new Date(b.start?.dateTime ?? b.start ?? '');
    const end   = new Date(b.end?.dateTime   ?? b.end   ?? '');
    if (!isNaN(start) && !isNaN(end)) {
      busyByCalendar[calId].push({ start, end });
    }
  });
});

