const dayOfWeek = new Date(dateStr + 'T12:00:00Z').getUTCDay();
const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;

const openTimeStr  = (isWeekend && branch.open_time_weekend)  ? branch.open_time_weekend  : (branch.open_time  || '08:00');
const closeTimeStr = (isWeekend && branch.close_time_weekend) ? branch.close_time_weekend : (branch.close_time || '18:00');

let dayStart = createUTCDate(dateStr, openTimeStr);
let dayEnd   = createUTCDate(dateStr, closeTimeStr);

