if (lastAtClose && !candidates.includes(dayEnd.getTime())) candidates.push(dayEnd.getTime());

for (const candidate of candidates) {
  const scanTime = new Date(candidate);
  const slotEnd = new Date(scanTime.getTime() + durationMs);

  // Saltar slots que aún no cumplen el período de confirmación  ← NUEVO
  if (scanTime < minAllowedTime) continue;

  for (const w of workshopItems) {
    const busy = busyByCalendar[w.calendar_id] || [];
    const isBusyCalendar = busy.some(b => scanTime < b.end && slotEnd > b.start);
    const isInternalBusy = internalBlocks.some(b => scanTime < b.end && slotEnd > b.start);

    if (!isBusyCalendar && !isInternalBusy) {
      const displayHour = scanTime.getUTCHours() - 3;
      const displayMin  = scanTime.getUTCMinutes();
      allFreeSlots.push({
        time: `${String(displayHour).padStart(2,'0')}:${String(displayMin).padStart(2,'0')}`,
        date_name: dateName,
        workshop_id: w.workshop_id,
        calendar_id: w.calendar_id
      });
      break;
    }
  }
}

// =========================
// FASE 2: Selección distribuida a lo largo del día
// =========================
let availableSlots = [];

if (allFreeSlots.length === 0) {
  // sin slots disponibles
} else if (allFreeSlots.length <= totalSlots) {
  availableSlots = allFreeSlots;
} else {
  const step = (allFreeSlots.length - 1) / (totalSlots - 1);
  const seen = new Set();
  for (let i = 0; i < totalSlots; i++) {
    const idx = Math.min(Math.round(i * step), allFreeSlots.length - 1);
    if (!seen.has(idx)) {
      seen.add(idx);
      availableSlots.push(allFreeSlots[idx]);
    }
  }
}

// =========================
// OUTPUT
// =========================
return [{
  json: {
    success: true,
    date: dateStr,
    date_name: dateName,
    total_free_slots: allFreeSlots.length,
    available_slots: availableSlots
  }
}];

